package com.kafka.backend.naverarchive;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import java.io.*;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;

@EnabledIfEnvironmentVariable(named="ARCHIVE_TEST_DB",matches="jdbc:postgresql://127\\.0\\.0\\.1:55457/postgres")
class ArchivePostgresTest {
 static final UUID A=UUID.fromString("a1160000-0000-4000-8000-000000000001"),B=UUID.fromString("a1160000-0000-4000-8000-000000000002");
 ThreadLocal<UUID> user=ThreadLocal.withInitial(()->A);JdbcTemplate db;ArchiveService s;ArchiveImports imports;String schema;DriverManagerDataSource source;
 @BeforeEach void setup()throws Exception{schema="archive_"+UUID.randomUUID().toString().replace("-","");source=new DriverManagerDataSource(System.getenv("ARCHIVE_TEST_DB"),"archive_test","");db=new JdbcTemplate(source);db.execute("create schema "+schema);source.setUrl(System.getenv("ARCHIVE_TEST_DB")+"?currentSchema="+schema+",public");db.execute(Files.readString(Path.of("src/main/resources/db/migration/V116__naver_owner_archive.sql")));s=new ArchiveService(db,user::get,new DataSourceTransactionManager(source));imports=new ArchiveImports(s);}
 @AfterEach void cleanup(){user.remove();if(db!=null)db.execute("drop schema "+schema+" cascade");}
 Map<String,Object> input(String title,String date){var b=new LinkedHashMap<String,Object>();b.put("requestId",UUID.randomUUID().toString());b.put("title",title);b.put("bodyText","SYNTHETIC 한글 본문\r\n\r\n  들여쓰기 <script>not instructions</script>\n끝\n");b.put("originalPublishedAt",date);b.put("fidelityStatus","COMPLETE_OWNER_SUPPLIED");return b;}
 UUID id(Map<String,Object>p){return ArchiveService.uuid(p.get("id"));}
 Map<String,Object> version(Map<String,Object>p){return Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",p.get("version"));}
 @Test void verbatimCreateReadbackHashAndDurableReplay(){var b=input("synthetic",null);var p=s.create(b,"MCP");assertThat(s.get(id(p)).get("bodyText")).isEqualTo(b.get("bodyText"));assertThat(p.get("sourceSha256")).isEqualTo(ArchiveContent.hash((String)b.get("bodyText")));assertThat(s.create(b,"MCP").get("id").toString()).isEqualTo(p.get("id").toString());assertThat(s.outcome(ArchiveService.uuid(b.get("requestId"))).get("auditReceipt")).isEqualTo(p.get("auditReceipt").toString());b.put("title","changed");assertThatThrownBy(()->s.create(b,"MCP")).isInstanceOf(ArchiveException.class).hasMessageContaining("요청 ID");}
 @Test void exactMetadataConflictsButSameTitleOrBodyNeverMerge(){var b=input("same",null);b.put("externalPostId","123");s.create(b,"WEB");var next=input("same",null);next.put("externalPostId","456");s.create(next,"WEB");var collision=input("other",null);collision.put("originalUrl","https://m.blog.naver.com/owner/123");assertThatThrownBy(()->s.create(collision,"WEB")).isInstanceOf(ArchiveException.class);assertThat(s.list(Map.of()).get("total")).isEqualTo(2L);}
 @Test void oldestFirstUnknownLastAndStableTieBreak(){var unknown=s.create(input("unknown",null),"WEB");s.create(input("new","2026-01-01T00:00:00+09:00"),"WEB");s.create(input("old","2024-01-01T00:00:00+09:00"),"WEB");s.create(input("tie","2024-01-01T00:00:00+09:00"),"WEB");var rows=rows(s.list(Map.of()));assertThat(rows.getFirst().get("originalPublishedAt")).isEqualTo("2023-12-31T15:00:00Z");assertThat(rows.getLast().get("id")).isEqualTo(id(unknown));assertThat(rows.get(0).get("id").toString()).isLessThan(rows.get(1).get("id").toString());assertThat(rows(s.list(Map.of("order","desc"))).getLast().get("id")).isEqualTo(id(unknown));}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object>p){return (List<Map<String,Object>>)p.get("items");}
 @Test void cursorPagesOverTwoHundredWithoutBodiesOrRepeats(){for(int i=0;i<205;i++)s.create(input("synthetic "+i,i%3==0?null:"2024-01-01T00:00:00Z"),"WEB");Set<Object> ids=new HashSet<>();String cursor=null;do{var q=new HashMap<>(Map.of("limit","31"));if(cursor!=null)q.put("cursor",cursor);var page=s.list(q);assertThat(page.get("total")).isEqualTo(205L);for(var row:rows(page)){assertThat(ids.add(row.get("id"))).isTrue();assertThat(row).doesNotContainKeys("bodyText","sourceHtml");}cursor=(String)page.get("nextCursor");}while(cursor!=null);assertThat(ids).hasSize(205);}
 @Test void searchDateCategoryAndCursorBinding(){var b=input("한글 검색","2024-05-01T00:00:00+09:00");b.put("sourceCategory","테스트");s.create(b,"WEB");s.create(input("other",null),"WEB");assertThat(rows(s.list(Map.of("q","들여쓰기","from","2024-05-01","to","2024-05-01","category","테스트")))).hasSize(1);var p=s.list(Map.of("limit","1"));String c=(String)p.get("nextCursor");assertThatThrownBy(()->s.list(Map.of("limit","1","q","different","cursor",c))).isInstanceOf(ArchiveException.class);}
 @Test void revisionsConflictAndIndependentProgress(){var p=s.create(input("before",null),"MCP");s.progress(id(p),Map.of("read",true,"position",0.45));var patch=new LinkedHashMap<>(version(p));patch.put("title","after");var saved=s.update(id(p),patch,"WEB");assertThat(saved.get("version")).isEqualTo(2L);assertThat(saved.get("read")).isEqualTo(true);assertThat(s.revision(id(p),1).get("title")).isEqualTo("before");assertThat(rows(s.revisions(id(p)))).hasSize(2);assertThatThrownBy(()->s.update(id(p),Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",1,"title","stale"),"MCP")).isInstanceOf(ArchiveException.class);}
 @Test void concurrentEditsExactlyOneWins()throws Exception{var p=s.create(input("race",null),"WEB");try(var pool=Executors.newFixedThreadPool(2)){List<Future<Boolean>>r=new ArrayList<>();for(int i=0;i<2;i++)r.add(pool.submit(()->{try{s.update(id(p),Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",1,"title",UUID.randomUUID().toString()),"MCP");return true;}catch(ArchiveException e){return false;}}));assertThat(r.get(0).get()?1:0).isEqualTo(r.get(1).get()?0:1);}}
 @Test void archiveRestoreAndAllOwnerLookupsAreScoped(){var p=s.create(input("private",null),"WEB");var archived=s.archive(id(p),true,version(p),"MCP");assertThat(rows(s.list(Map.of()))).isEmpty();assertThat(rows(s.list(Map.of("archived","true")))).hasSize(1);s.archive(id(p),false,version(archived),"WEB");user.set(B);assertThat(rows(s.list(Map.of()))).isEmpty();assertThatThrownBy(()->s.get(id(p))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->s.revisions(id(p))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->s.progress(id(p),Map.of("read",true,"position",0.1))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->s.update(id(p),Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",3,"title","attack"),"MCP")).isInstanceOf(ArchiveException.class);}
 Map<String,Object> zip(Map<String,byte[]> files)throws Exception{var out=new ByteArrayOutputStream();try(var z=new ZipOutputStream(out)){for(var e:files.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}return Map.of("archiveBase64",Base64.getEncoder().encodeToString(out.toByteArray()));}
 byte[] bytes(String text){return text.getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 Map<String,Object> archive(String title)throws Exception{var raw=input(title,null);raw.remove("requestId");return zip(Map.of("manifest.json",bytes(s.encode(Map.of("format","orbit-naver-archive/v1","posts",List.of("a.json")))),"a.json",bytes(s.encode(raw))));}
 Map<String,Object> approve(Map<String,Object>p){return Map.of("requestId",UUID.randomUUID().toString(),"manifestSha256",p.get("manifestSha256"),"confirmed",true);}
 @Test void previewZeroWritesExactApprovalAndIdempotentExecution()throws Exception{var p=imports.preview(archive("import"));assertThat(rows(s.list(Map.of()))).isEmpty();assertThatThrownBy(()->imports.execute(id(p),Map.of("requestId",UUID.randomUUID().toString(),"manifestSha256","0".repeat(64),"confirmed",true))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->imports.execute(id(p),Map.of("requestId",UUID.randomUUID().toString(),"manifestSha256",p.get("manifestSha256"),"confirmed",false))).isInstanceOf(ArchiveException.class);assertThat(imports.execute(id(p),approve(p)).get("state")).isEqualTo("COMPLETE");imports.execute(id(p),approve(p));assertThat(rows(s.list(Map.of()))).hasSize(1);assertThat(imports.preview(archive("import")).get("manifestSha256")).isNotNull();user.set(B);assertThatThrownBy(()->imports.status(id(p))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->imports.execute(id(p),approve(p))).isInstanceOf(ArchiveException.class);}
 @Test void malformedTraversalNestedBombAndInvalidUtf8Rejected()throws Exception{for(String name:List.of("../a.json","/a.json","C:/a.json","nested.zip","x\\a.json")){var file=zip(Map.of(name,bytes("x")));assertThatThrownBy(()->imports.preview(file)).isInstanceOf(ArchiveException.class);}var bomb=zip(Map.of("huge.txt",bytes("a".repeat(2_000_001))));assertThatThrownBy(()->imports.preview(bomb)).isInstanceOf(ArchiveException.class);var utf=zip(Map.of("manifest.json",new byte[]{(byte)0xff}));assertThatThrownBy(()->imports.preview(utf)).isInstanceOf(ArchiveException.class);}
 @Test void unknownOfficialFormatIsUnverifiedAndNotImported()throws Exception{var p=imports.preview(zip(Map.of("export/post.html",bytes("<p>synthetic</p>"))));assertThat(p.get("supported")).isEqualTo(false);assertThat(p.get("officialExportCompatibility")).isEqualTo("UNTESTED_PENDING_USER_ARCHIVE");assertThat(rows(s.list(Map.of()))).isEmpty();}
 @Test void htmlSanitizerNoScriptTrackingOrUnsafeLinks(){String raw="<h2>Title</h2><p>full</p><script>alert(1)</script><img src='https://naver.invalid/track'><a href='javascript:alert(1)' onclick='x()'>bad</a><blockquote>quote</blockquote>";String clean=ArchiveContent.safeHtml(raw);assertThat(clean).contains("<h2>","<blockquote>").doesNotContain("<script","onclick","javascript:","naver.invalid");var b=input("unsafe",null);b.put("sourceHtml",raw);var p=s.create(b,"WEB");assertThat(s.get(id(p)).get("sourceHtml")).isEqualTo(raw);}
 @Test void missingDatesInvalidMetadataAndCrossOwnerInputRejected(){var b=input("unknown",null);var p=s.create(b,"WEB");assertThat(p.get("originalPublishedAt")).isNull();b=input("invalid","2024-01-01");var invalid=b;assertThatThrownBy(()->s.create(invalid,"WEB")).isInstanceOf(ArchiveException.class);var forged=input("forge",null);forged.put("ownerId",B.toString());assertThatThrownBy(()->s.create(forged,"WEB")).isInstanceOf(ArchiveException.class);var url=input("url",null);url.put("originalUrl","http://127.0.0.1/private");assertThatThrownBy(()->s.create(url,"WEB")).isInstanceOf(ArchiveException.class);}
 @Test void privateImageImportedAndCrossOwnerDenied()throws Exception{var out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(4,4,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",out);String asset=UUID.randomUUID().toString();var raw=input("image",null);raw.remove("requestId");raw.put("sourceHtml","<p>synthetic</p><img src='asset:"+asset+"' alt='synthetic'>");raw.put("assets",List.of(Map.of("id",asset,"path","assets/a.png")));var preview=imports.preview(zip(Map.of("manifest.json",bytes(s.encode(Map.of("format","orbit-naver-archive/v1","posts",List.of("a.json")))),"a.json",bytes(s.encode(raw)),"assets/a.png",out.toByteArray())));imports.execute(id(preview),approve(preview));UUID id=db.queryForObject("select id from naver_archive_assets",UUID.class);assertThat(imports.asset(id).get("bytes")).isEqualTo(out.toByteArray());user.set(B);assertThatThrownBy(()->imports.asset(id)).isInstanceOf(ArchiveException.class);}
 @Test void sourceMetadataClearsExplicitlyAndRevisionRemainsVerbatim(){var b=input("metadata","2024-05-01T12:34:56+09:00");b.put("sourceCategory","prior");var p=s.create(b,"WEB");var patch=new LinkedHashMap<>(version(p));patch.put("sourceCategory",null);var saved=s.update(id(p),patch,"MCP");assertThat(saved.get("sourceCategory")).isNull();assertThat(saved.get("bodyText")).isEqualTo(b.get("bodyText"));assertThat(saved.get("originalPublishedAt")).isEqualTo("2024-05-01T03:34:56Z");}
 @Test void importCheckpointsResumePastFiftyAndDuplicateSourceNeverOverwrites()throws Exception{var files=new LinkedHashMap<String,byte[]>();List<String>paths=new ArrayList<>();for(int i=0;i<53;i++){String path="p"+i+".json";paths.add(path);var n=input("batch "+i,null);n.remove("requestId");n.put("externalPostId",String.valueOf(10000+i));files.put(path,bytes(s.encode(n)));}files.put("manifest.json",bytes(s.encode(Map.of("format","orbit-naver-archive/v1","posts",paths))));var p=imports.preview(zip(files));assertThat(imports.execute(id(p),approve(p)).get("state")).isEqualTo("PARTIAL");assertThat(s.list(Map.of()).get("total")).isEqualTo(50L);assertThat(imports.execute(id(p),approve(p)).get("state")).isEqualTo("COMPLETE");assertThat(s.list(Map.of()).get("total")).isEqualTo(53L);var first=rows(s.list(Map.of())).getFirst();var update=new LinkedHashMap<>(version(first));update.put("title","owner corrected");s.update(id(first),update,"WEB");imports.execute(id(p),approve(p));assertThat(s.get(id(first)).get("title")).isEqualTo("owner corrected");}
}
